insert into public.project_highlights (project_id, label, detail, sort_order)
select p.id, v.label, v.detail, v.ord from p, (values
  ('End-to-end ordering', 'Authentication, restaurant browsing, cuisine filtering, search, cart, address and payment selection, order placement, history and cancellation — against a live REST API rather than mock data.', 0),
  ('English / Arabic with real RTL', 'Layout mirroring via Directionality and EdgeInsetsDirectional throughout, so nothing is pinned to the left in an RTL locale. 149 strings in both languages.', 1),
  ('ICU plurals, not an English-shaped guess', 'Arabic has six plural forms. The ARB files use real ICU plural logic — zero, one, two, few, many, other — instead of a one/other split that would be wrong most of the time.', 2),
  ('Secure session handling', 'Tokens stored through flutter_secure_storage, which is backed by the Android Keystore and the iOS Keychain rather than shared preferences.', 3),
  ('Custom Dio interceptors', 'An API-key interceptor for authentication and a hand-written logging interceptor that redacts credentials before anything reaches the console.', 4),
  ('Tested at four configurations', 'Every screen renders on a standard phone, a 320×568 phone, at 1.6× accessibility text scale, and in Arabic. A RenderFlex overflow throws during layout, so a clean render is itself the assertion.', 5)
) as v(label, detail, ord)
  returning 1
),
ins2 as (
insert into public.project_decisions (project_id, title, detail, sort_order)
select p.id, v.title, v.detail, v.ord from p, (values
  ('Only show what is true', 'The design mocks up star ratings, delivery fees and delivery times. The API returns none of them. Rather than invent numbers, restaurant cards show facts that exist — city, dish count, and whether there is parking. The same reasoning removed the social sign-in buttons, because there is no OAuth, and kept Forgot Password honest about the fact that no email will arrive.', 0),
  ('Restaurant photos from an API with no restaurant images', '/Restaurant returns no image field. Instead of shipping placeholder assets, the repository also fetches /Restaurant/items — all 93 dishes in one request — and gives each restaurant its first dish''s photo. That call is deliberately allowed to fail silently: photos are enrichment and must not cost the whole screen.', 1),
  ('The cart cannot span restaurants', 'makeorder puts the restaurant in the URL, so one order cannot cover two. That constraint is enforced in state through CartState.acceptsFrom and surfaced as a prompt when a user adds from somewhere else — not as a confusing failure at checkout.', 2),
  ('Cards keep only the last four digits', 'The number entered derives the brand and last four, then is discarded. Expiry and CVC are validated for shape and never stored, because nothing here could legitimately use them. A test asserts the full number never reaches storage.', 3),
  ('Tolerant API parsing', '/Order needs a key, so its response shape could not be inspected while writing the model. Order.tryParse accepts several plausible key spellings and treats every field but the id as optional, so an unexpected payload yields a sparser card rather than a TypeError on screen.', 4),
  ('A logger that redacts', 'Dio''s own LogInterceptor dumps the query string and body — and this API sends the password as a query parameter on login. The hand-written interceptor redacts passwords, API keys and user codes, and reports the shape of list responses rather than their contents.', 5)
) as v(title, detail, ord)
  returning 1
),
