-- Food Recipe App -----------------------------------------------
with p as (
  insert into public.projects
    (slug, title, subtitle, summary, body, role, category, period, year,
     featured, sort_order, status, repo_url, live_url, paper_url,
     cover_url, video_url, poster_url, architecture)
  values (
    'recipe-app',
    'Food Recipe App',
    'Clean Architecture, layer by layer',
    'A recipe browser built as a textbook separation of data, domain and presentation. Every feature owns its own three layers, use cases are single-purpose classes, and nothing is constructed by hand — GetIt resolves the graph.',
    '["Browse featured and popular recipes, explore categories, open a recipe for its details and creator, search across the catalogue, and keep a shopping cart of what you need to buy.","The point of this project was the shape rather than the surface. Each feature — auth, recipes, search, cart, profile — carries its own data, domain and presentation folders. The domain layer holds entities and use cases and imports nothing from Flutter; the data layer maps remote JSON into those entities; presentation only talks to providers.","Failures are modelled rather than thrown into the void: a Failure type in the core layer, exceptions converted at the data boundary, and a ViewStatus that presentation can render without knowing what went wrong underneath."]'::jsonb,
    'Solo developer — architecture, API integration, state management',
    'Mobile Application',
    '07/2026',
    2026,
    true,
    2,
    'published',
    'https://github.com/NourEkramy/Recipes-App',
    NULL,
    NULL,
    '/media/recipe-app/app-home.webp',
    '/media/video/recipe-app.mp4',
    '/media/poster/recipe-app.webp',
    '{"name":"Clean Architecture (data / domain / presentation)","summary":"Five features, each split into three layers with dependencies pointing inwards. Domain knows nothing about Dio or Flutter; data implements the repository interfaces domain declares; presentation consumes use cases through Provider. GetIt wires the graph in a single service locator.","layers":[{"name":"Domain","detail":"Entities, repository interfaces and one class per use case. Pure Dart, no Flutter import."},{"name":"Data","detail":"Remote data sources, models that map JSON to entities, and repository implementations."},{"name":"Presentation","detail":"Providers holding view state, screens, and reusable widgets."},{"name":"Core","detail":"Dio client, API constants, Failure and Exception types, the base UseCase contract and ViewStatus."}],"tree":"lib/\n├── main.dart\n├── app/\n│   └── main_navigation.dart\n├── Core/\n│   ├── constants/            # api_constants, app_colors\n│   ├── di/                   # service_locator (GetIt)\n│   ├── error/                # exceptions, failures\n│   ├── network/              # dio_client\n│   └── usecases/             # usecase, view_status\n└── features/\n    ├── auth/\n    │   ├── data/             # datasources, models, repositories\n    │   ├── domain/           # entities, repositories, usecases\n    │   └── presentation/     # providers, screens\n    ├── recipes/\n    │   ├── data/             # recipe + creator models, remote data source\n    │   ├── domain/           # get_featured, get_popular, get_categories,\n    │   │                     # get_recipe_details, get_creator\n    │   └── presentation/     # home, details, search screens + widgets\n    ├── search/\n    ├── cart/\n    └── profile/"}'::jsonb
  )
  returning id
),
