select p.id, v.label, v.detail, v.ord from p, (values
  ('Strict layer separation', 'Presentation depends on domain, data implements domain. The dependency arrow never points outward, so the business rules could be lifted into another app unchanged.', 0),
  ('One class per use case', 'GetFeaturedRecipes, GetPopularRecipes, GetCategories, GetRecipeDetails, GetCreator, SearchRecipes and Login each implement a shared UseCase contract — small, nameable, individually testable.', 1),
  ('Dependency injection with GetIt', 'A single service_locator registers Dio, data sources, repositories, use cases and providers. Screens resolve what they need instead of constructing it, which keeps them trivially swappable in tests.', 2),
  ('Modelled failures', 'Exceptions raised at the data boundary are converted into Failure values, and a ViewStatus enum drives loading, error and success rendering consistently across every screen.', 3),
  ('Composable UI', 'Featured carousel, category list, editor''s choice card, popular recipe card, author row, search thumbnail and cart card are each standalone widgets rather than nested build methods.', 4)
) as v(label, detail, ord)
  returning 1
),
