-- Lupira --------------------------------------------------------
with p as (
  insert into public.projects
    (slug, title, subtitle, summary, body, role, category, period, year,
     featured, sort_order, status, repo_url, live_url, paper_url,
     cover_url, video_url, poster_url, architecture)
  values (
    'lupira-app',
    'Lupira',
    'Early lupus detection — graduation project and published research',
    'A Flutter application that screens for systemic lupus erythematosus from reported symptoms and laboratory results, scored against established clinical criteria. Backed by a Node.js and MongoDB API, and published as a co-authored research paper reporting 96.95% detection accuracy.',
    '["Patients answer a structured clinical questionnaire and enter laboratory values; the app evaluates them against recognised SLE criteria and returns a detection result, which is stored so the history can be reviewed over time.","It carries the parts a real medical tool needs: account creation and authentication, a diagnosis tab, saved reports, article content, profile and settings management, and full Arabic/English localisation with RTL support and deep linking.","This was my graduation project. The accompanying research was co-authored and published, reporting 96.95% accuracy in SLE detection."]'::jsonb,
    'Flutter developer — mobile client, API integration, localisation; co-author on the paper',
    'Healthcare / Research',
    '2024 — 2025',
    2025,
    true,
    3,
    'published',
    'https://github.com/NourEkramy/Lupira-App',
    NULL,
    NULL,
    '/media/lupira-app/screen-028.webp',
