-- Shopping Demo App ---------------------------------------------
with p as (
  insert into public.projects
    (slug, title, subtitle, summary, body, role, category, period, year,
     featured, sort_order, status, repo_url, live_url, paper_url,
     cover_url, video_url, poster_url, architecture)
  values (
    'shopping-demo-app',
    'Shopping Demo App',
    'MVVM, reduced to its essentials',
    'A compact shopping client written to demonstrate MVVM cleanly: models, services, view models and views in four separate folders, with Provider driving the bindings and Dio behind a service layer.',
    '["Products load from a remote API into a home grid; tapping through gives a detail view, and items can be added to a cart that tracks quantities and totals.","Written as a mentorship exercise, the value is in the discipline rather than the feature count. The views hold no logic, the view models hold no widgets, and the services are the only place an HTTP call exists — so the same view model would work unchanged against a different backend."]'::jsonb,
    'Solo developer — MVVM structure, API layer, state management',
    'Mobile Application',
    '2026',
    2026,
    false,
    4,
    'published',
    'https://github.com/NourEkramy/Mentor_Ship_Task2',
    NULL,
    NULL,
    '/media/shopping-demo-app/collection-detail.webp',
    NULL,
    NULL,
    '{"name":"MVVM with a service layer","summary":"Four folders, one responsibility each. Views render and dispatch; view models hold observable state and call services; services own the Dio calls and return models. Provider connects view models to the widget tree.","layers":[{"name":"Models","detail":"product and cart_item — plain data with JSON mapping."},{"name":"Services","detail":"api_services and product_service — the only layer aware of Dio."},{"name":"ViewModels","detail":"home_viewmodel and cart_viewmodel — state plus the operations that change it."},{"name":"Views & Widgets","detail":"home and cart screens composed from product_card and cart_item_card."}],"tree":"lib/\n├── main.dart\n├── models/\n│   ├── product.dart\n│   └── cart_item.dart\n├── services/\n│   ├── api_services.dart\n│   └── product_service.dart\n├── viewmodels/\n│   ├── home_viewmodel.dart\n│   └── cart_viewmodel.dart\n├── views/\n│   ├── home/home_screen.dart\n│   └── cart/cart_screen.dart\n└── widgets/\n    ├── product_card.dart\n    └── cart_item_card.dart"}'::jsonb
  )
  returning id
),
