     cover_url, video_url, poster_url, architecture)
  values (
    'order-tracking-notifications',
    'Order Tracking & Notifications',
    'Firebase Cloud Messaging with a live delivery timeline',
    'Built at the ISupply Flutter hackathon under time pressure: push notifications through Firebase Cloud Messaging, local notifications for foreground delivery, runtime permission handling, and an order timeline that advances through each delivery stage.',
    '["A push arrives from Firebase Cloud Messaging and the order status moves forward. In the foreground, flutter_local_notifications presents it so a message is never silently swallowed; in the background, FCM handles presentation itself.","Notification permission is requested at runtime through permission_handler rather than assumed, and the tracking screen renders the order''s progress as a timeline so the current stage is legible at a glance.","Built individually during the hackathon with a focus on API integration, state handling and UI under a hard deadline."]'::jsonb,
    'Solo developer — hackathon prototype',
    'Hackathon Prototype',
    '06/2025',
    2025,
    false,
    5,
    'published',
    'https://github.com/NourEkramy/Order-Tracking-Notification',
    NULL,
    NULL,
    '/media/poster/order-tracking-notifications.webp',
    '/media/video/order-tracking-notifications.mp4',
    '/media/poster/order-tracking-notifications.webp',
    '{"name":"Focused single-flow prototype","summary":"A deliberately small surface: one tracking screen composed from two widgets, with Firebase initialised from generated options and messaging wired up in main. Scope was the constraint, so the structure stays flat and readable rather than layered for its own sake.","layers":[{"name":"main.dart","detail":"Firebase init, FCM listeners and local notification setup."},{"name":"Screens","detail":"order_tracking_screen — the single tracking surface."},{"name":"Widgets","detail":"order_card_widget and order_progress_widget."}],"tree":"lib/\n├── main.dart                     # Firebase init + FCM + local notifications\n├── firebase_options.dart         # generated platform configuration\n├── Screens/\n│   └── order_tracking_screen.dart\n└── Widgets/\n    ├── order_card_widget.dart\n    └── order_progress_widget.dart"}'::jsonb
  )
  returning id
),
